-- ── Query 1 ────────────────────────────────────────────────────────────
SELECT     TRUNC(SYSDATE)                                       AS \"Report Date\",     pim.DEPT                                             AS \"Department Number\",     d.DEPT_NAME                                          AS \"Department Name\",     pim.CLASS                                            AS \"Class Number\",     c.CLASS_NAME                                         AS \"Class Name\",     pim.SUBCLASS                                         AS \"Subclass Number\",     sc.SUB_NAME                                          AS \"Subclass Name\",     sd.ITEM                                              AS \"Primary Item ID\",     pim.ITEM_DESC                                        AS \"Primary Item Description\",     pim.STANDARD_UOM                                     AS \"Primary Unit of Measure\",     pim.STATUS                                           AS \"Primary Item Status\",     pim.PACK_IND                                         AS \"Primary Pack Indicator\",     pils.STOCK_ON_HAND                                   AS \"Primary Item Stock on Hand\",     pils.AV_COST                                         AS \"Primary Item Weighted Average Cost\",     pil.SELLING_UNIT_RETAIL                              AS \"Primary Item Retail\",     pil.STATUS                                           AS \"Primary Item Location Status\",     CASE pil.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                  AS \"Primary Item Location Status Description\",     sd.SUB_ITEM                                          AS \"Substitute Item ID\",     sim.ITEM_DESC                                        AS \"Substitute Item Description\",     sim.STANDARD_UOM                                     AS \"Substitute Item Unit of Measure\",     sim.STATUS                                           AS \"Substitute Item Status\",     sim.DEPT                                             AS \"Substitute Item Department\",     sim.CLASS                                            AS \"Substitute Item Class\",     sils.STOCK_ON_HAND                                   AS \"Substitute Item Stock on Hand\",     sils.AV_COST                                         AS \"Substitute Item Weighted Average Cost\",     sil.SELLING_UNIT_RETAIL                              AS \"Substitute Item Retail\",     sil.STATUS                                           AS \"Substitute Item Location Status\",     CASE sil.STATUS         WHEN 'A' THEN 'Active'         WHEN 'C' THEN 'Discontinued'         WHEN 'I' THEN 'Inactive'         WHEN 'D' THEN 'Delete'     END                                                  AS \"Substitute Item Location Status Description\",     sd.LOCATION                                          AS \"Location ID\",     sd.LOC_TYPE                                          AS \"Location Type\",     CASE sd.LOC_TYPE         WHEN 'S' THEN 'Store'         WHEN 'W' THEN 'Warehouse'     END                                                  AS \"Location Type Description\",     CASE sd.LOC_TYPE         WHEN 'S' THEN st.STORE_NAME         WHEN 'W' THEN wh.WH_NAME     END                                                  AS \"Location Name\",     sd.START_DATE                                        AS \"Substitution Start Date\",     sd.END_DATE                                          AS \"Substitution End Date\",     TRUNC(SYSDATE) - TRUNC(NVL(sd.START_DATE, SYSDATE)) AS \"Days Active\",     TRUNC(NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999))         - TRUNC(SYSDATE)                                 AS \"Days Remaining\",     CASE         WHEN TRUNC(SYSDATE) BETWEEN              NVL(sd.START_DATE, TRUNC(SYSDATE))              AND NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999)         THEN 'ACTIVE'         WHEN TRUNC(SYSDATE) &lt; NVL(sd.START_DATE, TRUNC(SYSDATE))         THEN 'FUTURE'         ELSE 'EXPIRED'     END                                                  AS \"Substitution Record Status\",     CASE         WHEN sd.END_DATE IS NOT NULL              AND sd.END_DATE BETWEEN TRUNC(SYSDATE) AND TRUNC(SYSDATE) + 7         THEN 'EXPIRING IN 7 DAYS'         WHEN sd.END_DATE IS NOT NULL              AND sd.END_DATE BETWEEN TRUNC(SYSDATE) + 8 AND TRUNC(SYSDATE) + 30         THEN 'EXPIRING IN 30 DAYS'         WHEN sd.END_DATE IS NULL         THEN 'NO EXPIRY SET'         ELSE 'VALID'     END                                                  AS \"Expiry Urgency\",     sd.SUBSTITUTE_REASON                                 AS \"Substitution Reason Code\",     CASE sd.SUBSTITUTE_REASON         WHEN 'O' THEN 'Out of Stock'         WHEN 'D' THEN 'Discontinued'         WHEN 'S' THEN 'Seasonal Replacement'         WHEN 'P' THEN 'Promotional Substitute'         ELSE NVL(sd.SUBSTITUTE_REASON, 'Not Specified')     END                                                  AS \"Substitution Reason Description\",     sd.PICK_PRIORITY                                     AS \"Pick Priority\",     ril.REPL_METHOD                                      AS \"Replenishment Method\",     CASE ril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'F'  THEN 'Floating Point'         ELSE NVL(ril.REPL_METHOD, 'NOT ON REPLENISHMENT')     END                                                  AS \"Replenishment Method Description\",     ril.STOCK_CAT                                        AS \"Stock Category\",     ril.REPL_ORDER_CTRL                                  AS \"Order Control\",     ril.SOURCE_WH                                        AS \"Source Warehouse\",     sril.REPL_METHOD                                     AS \"Substitute Replenishment Method\",     CASE sril.REPL_METHOD         WHEN 'C'  THEN 'Constant'         WHEN 'D'  THEN 'Dynamic'         WHEN 'M'  THEN 'Min/Max'         WHEN 'T'  THEN 'Time Supply'         WHEN 'SO' THEN 'Store Orders'         WHEN 'F'  THEN 'Floating Point'         ELSE NVL(sril.REPL_METHOD, 'NOT ON REPLENISHMENT')     END                                                  AS \"Substitute Replenishment Method Description\",     CASE         WHEN NVL(sils.STOCK_ON_HAND, 0) &gt; 0              AND sil.STATUS IN ('A', 'C')         THEN 'SUBSTITUTE AVAILABLE'         WHEN NVL(sils.STOCK_ON_HAND, 0) = 0         THEN 'SUBSTITUTE OUT OF STOCK'         WHEN sil.STATUS NOT IN ('A', 'C')         THEN 'SUBSTITUTE ITEM/LOC NOT ACTIVE'         ELSE 'REVIEW REQUIRED'     END                                                  AS \"Substitute Availability Status\",     ROUND(NVL(sil.SELLING_UNIT_RETAIL, 0)           - NVL(pil.SELLING_UNIT_RETAIL, 0), 2)         AS \"Retail Price Difference\",     CASE         WHEN pil.SELLING_UNIT_RETAIL &gt; 0         THEN ROUND(              (NVL(sil.SELLING_UNIT_RETAIL, 0)               - NVL(pil.SELLING_UNIT_RETAIL, 0))              / pil.SELLING_UNIT_RETAIL * 100              , 2)     END                                                  AS \"Retail Price Difference Percent\" FROM     MFCS_RDS.RDS_WV_SUB_ITEMS_DETAIL       sd     JOIN  MFCS_RDS.RDS_WV_SUB_ITEMS_HEAD   sh    ON  sd.ITEM      = sh.ITEM                                                   AND sd.LOCATION  = sh.LOCATION     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       pim   ON  sd.ITEM     = pim.ITEM     JOIN  MFCS_RDS.RDS_WV_DEPS              d     ON  pim.DEPT    = d.DEPT     JOIN  MFCS_RDS.RDS_WV_CLASS             c     ON  pim.DEPT    = c.DEPT                                                   AND pim.CLASS   = c.CLASS     JOIN  MFCS_RDS.RDS_WV_SUBCLASS          sc    ON  pim.DEPT    = sc.DEPT                                                   AND pim.CLASS   = sc.CLASS                                                   AND pim.SUBCLASS = sc.SUBCLASS     JOIN  MFCS_RDS.RDS_WV_ITEM_MASTER       sim   ON  sd.SUB_ITEM = sim.ITEM     LEFT JOIN MFCS_RDS.RDS_WV_STORE         st    ON  sd.LOCATION = st.STORE                                                   AND sd.LOC_TYPE = 'S'     LEFT JOIN MFCS_RDS.RDS_WV_WH            wh    ON  sd.LOCATION = wh.WH                                                   AND sd.LOC_TYPE = 'W'     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      pil   ON  sd.ITEM     = pil.ITEM                                                   AND sd.LOCATION  = pil.LOC                                                   AND sd.LOC_TYPE  = pil.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  pils  ON  sd.ITEM     = pils.ITEM                                                   AND sd.LOCATION  = pils.LOC                                                   AND sd.LOC_TYPE  = pils.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC      sil   ON  sd.SUB_ITEM = sil.ITEM                                                   AND sd.LOCATION  = sil.LOC                                                   AND sd.LOC_TYPE  = sil.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_ITEM_LOC_SOH  sils  ON  sd.SUB_ITEM = sils.ITEM                                                   AND sd.LOCATION  = sils.LOC                                                   AND sd.LOC_TYPE  = sils.LOC_TYPE     LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC ril   ON  sd.ITEM     = ril.ITEM                                                   AND sd.LOCATION  = ril.LOCATION     LEFT JOIN MFCS_RDS.RDS_WV_REPL_ITEM_LOC sril  ON  sd.SUB_ITEM = sril.ITEM                                                   AND sd.LOCATION  = sril.LOCATION WHERE     TRUNC(SYSDATE) &gt;= NVL(sd.START_DATE, TRUNC(SYSDATE))     AND TRUNC(SYSDATE) &lt;= NVL(sd.END_DATE, TRUNC(SYSDATE) + 999999) ORDER BY     CASE         WHEN NVL(sils.STOCK_ON_HAND,0) &gt; 0 AND sil.STATUS IN ('A','C')              THEN 'SUBSTITUTE AVAILABLE'         WHEN NVL(sils.STOCK_ON_HAND,0) = 0              THEN 'SUBSTITUTE OUT OF STOCK'         WHEN sil.STATUS NOT IN ('A','C')              THEN 'SUBSTITUTE ITEM/